<?php $title = ['in'=>'ثبت ورود کالا','out'=>'ثبت خروج کالا','transfer'=>'انتقال کالا بین انبارها','adjustment'=>'اصلاح موجودی'][$type] ?? 'ثبت گردش'; ?>
<div class="card"><form method="post" action="<?= e(base_url('movement/save')) ?>" data-autosave="movement"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="type" value="<?= e($type) ?>"><div class="grid"><div class="col-4"><label>شماره ثبت</label><input name="reference_no" value="<?= e($reference) ?>" required></div><div class="col-4"><label>کالا</label><select name="item_id" required><option value="">انتخاب کنید</option><?php foreach($items as $i): ?><option value="<?= e($i['id']) ?>"><?= e($i['name'].' - '.$i['sku']) ?></option><?php endforeach; ?></select></div><div class="col-4"><label>مقدار</label><input type="number" step="0.001" min="0.001" name="quantity" required></div><?php if($type !== 'in'): ?><div class="col-4"><label>از انبار</label><select name="from_warehouse_id" required><option value="">انتخاب کنید</option><?php foreach($warehouses as $w): ?><option value="<?= e($w['id']) ?>"><?= e($w['name']) ?></option><?php endforeach; ?></select></div><?php endif; ?><?php if($type !== 'out'): ?><div class="col-4"><label>به انبار</label><select name="to_warehouse_id" required><option value="">انتخاب کنید</option><?php foreach($warehouses as $w): ?><option value="<?= e($w['id']) ?>"><?= e($w['name']) ?></option><?php endforeach; ?></select></div><?php endif; ?><?php if($type === 'in'): ?><div class="col-4"><label>تامین‌کننده</label><select name="supplier_id"><option value="">-</option><?php foreach($suppliers as $s): ?><option value="<?= e($s['id']) ?>"><?= e($s['name']) ?></option><?php endforeach; ?></select></div><?php endif; ?><?php if($type === 'out'): ?><div class="col-4"><label>مشتری</label><select name="customer_id"><option value="">-</option><?php foreach($customers as $c): ?><option value="<?= e($c['id']) ?>"><?= e($c['name']) ?></option><?php endforeach; ?></select></div><?php endif; ?><div class="col-12"><label>توضیحات</label><textarea name="notes"></textarea></div></div><button class="btn">ثبت و ساخت بارکد/رسید</button></form></div>
